	CONSTRAINT "judgement_compensations_incident_id_user_id_unique" UNIQUE("incident_id","user_id"),
	CONSTRAINT "judgement_compensations_amount_check" CHECK ("judgement_compensations"."amount_coin" > 0),
	CONSTRAINT "judgement_compensations_outcome_check" CHECK ("judgement_compensations"."outcome" IN ('paid', 'closed') AND ("judgement_compensations"."outcome" = 'paid') = ("judgement_compensations"."ledger_entry_id" IS NOT NULL)),
	CONSTRAINT "judgement_compensations_user_reason_check" CHECK (btrim("judgement_compensations"."user_reason") <> '' AND char_length("judgement_compensations"."user_reason") <= 500),
