-- Hand-edited: which ledger accounts each type moves Coin between, 0077's rows and
-- JUDGEMENT_COMPENSATION's — a mint into a user ledger account only (LEDGER_ENTRY_RULES,
-- @buddha/shared ledger.ts, which ledger.test.ts keeps equal to this for every type and pair).
-- Same signature, so 0060's trigger (`ledger_entries_check`) calls this body from the commit on.
CREATE OR REPLACE FUNCTION ledger_entry_direction_allowed(entry_type text, from_kind text, to_kind text)
RETURNS boolean
LANGUAGE sql IMMUTABLE AS $$
  SELECT (entry_type, coalesce(from_kind, '-'), coalesce(to_kind, '-')) IN (VALUES
    ('START_GRANT', '-', 'user'),
    ('TREASURY_MINT', '-', 'treasury'),
    ('BOT_ALLOCATION', 'treasury', 'market_maker_funds'),
    ('BOT_RECALL', 'market_maker_funds', 'treasury'),
    ('PAIR_MINT_COLLATERAL', 'user', 'market_collateral'),
    ('PAIR_MINT_COLLATERAL', 'market_maker_funds', 'market_collateral'),
    ('PAIR_BURN_RETURN', 'market_collateral', 'market_maker_funds'),
    ('TRADE_FILL', 'user', 'user'),
    ('TRADE_FILL', 'user', 'market_maker_funds'),
    ('TRADE_FILL', 'market_maker_funds', 'user'),
    ('SETTLEMENT_PAYOUT', 'market_collateral', 'user'),
    ('SETTLEMENT_PAYOUT', 'market_collateral', 'market_maker_funds'),
    ('CLOSURE_FORFEIT', 'user', '-'),
    ('RECONCILIATION_CORRECTION', 'treasury', 'user'),
    ('RECONCILIATION_CORRECTION', 'treasury', 'market_collateral'),
    ('RECONCILIATION_CORRECTION', 'market_collateral', 'treasury'),
    ('RECONCILIATION_CORRECTION', 'treasury', 'market_maker_funds'),
    ('RECONCILIATION_CORRECTION', 'market_maker_funds', 'treasury'),
    ('DEPOSIT', '-', 'user'),
    ('BONUS', '-', 'user'),
    ('PAYMENT_CANCEL', 'user', '-'),
    ('PAYMENT_CANCEL_REVERSAL', '-', 'user'),
    ('REGRANT', '-', 'user'),
    ('JUDGEMENT_COMPENSATION', '-', 'user')
  );
$$;--> statement-breakpoint
-- Hand-edited: 0060's `ledger_entries_check` (its only definition), copied verbatim but for one
-- clause — the market of an event with no market account on either side: a fill between two
-- people names its market (0060), and now so does a 판정 오류 보상, the mint that compensates a
-- market's judgement error (LEDGER_ENTRY_RULES `market: 'required'`; 144-12's 시장 링크, the
-- wallet's `?marketId=` filter and the recap read `ledger_entries.market_id`). Every other type
-- still names none. Every market-scoped ledger reader filters by type, so none counts the new
-- entry as the market's money (ADR-0166). Same signature, so 0060's trigger calls this body.
CREATE OR REPLACE FUNCTION ledger_entries_check() RETURNS trigger
LANGUAGE plpgsql SET search_path = pg_catalog, public, pg_temp AS $$
DECLARE
  from_kind text;
  from_market uuid;
  to_kind text;
  to_market uuid;
  latest_id bigint;
BEGIN
  IF NEW.from_account_id IS NOT NULL THEN
    SELECT a.kind::text, a.market_id INTO from_kind, from_market
      FROM ledger_accounts a WHERE a.id = NEW.from_account_id;
  END IF;
  IF NEW.to_account_id IS NOT NULL THEN
    SELECT a.kind::text, a.market_id INTO to_kind, to_market
      FROM ledger_accounts a WHERE a.id = NEW.to_account_id;
  END IF;
  IF NOT ledger_entry_direction_allowed(NEW.type::text, from_kind, to_kind) THEN
    RAISE EXCEPTION 'a % event does not move Coin from % to %', NEW.type,
      coalesce(from_kind, 'a mint'), coalesce(to_kind, 'a burn')
      USING ERRCODE = 'integrity_constraint_violation', CONSTRAINT = TG_NAME;
  END IF;
  IF (from_market IS NOT NULL AND from_market IS DISTINCT FROM NEW.market_id)
     OR (to_market IS NOT NULL AND to_market IS DISTINCT FROM NEW.market_id)
     OR (from_market IS NULL AND to_market IS NULL
         AND (NEW.market_id IS NOT NULL)
             <> (NEW.type::text IN ('TRADE_FILL', 'JUDGEMENT_COMPENSATION'))) THEN
    RAISE EXCEPTION 'a % event names the market of its accounts, and only then a market', NEW.type
      USING ERRCODE = 'integrity_constraint_violation', CONSTRAINT = TG_NAME;
  END IF;
  PERFORM 1 FROM balances b
   WHERE b.account_id IN (NEW.from_account_id, NEW.to_account_id)
   ORDER BY b.account_id
     FOR UPDATE;
  SELECT max(latest.id) INTO latest_id FROM (
    (SELECT e.id FROM ledger_entries e WHERE e.from_account_id = NEW.from_account_id
      ORDER BY e.id DESC LIMIT 1)
    UNION ALL
    (SELECT e.id FROM ledger_entries e WHERE e.to_account_id = NEW.from_account_id
      ORDER BY e.id DESC LIMIT 1)
    UNION ALL
    (SELECT e.id FROM ledger_entries e WHERE e.from_account_id = NEW.to_account_id
      ORDER BY e.id DESC LIMIT 1)
    UNION ALL
    (SELECT e.id FROM ledger_entries e WHERE e.to_account_id = NEW.to_account_id
      ORDER BY e.id DESC LIMIT 1)
  ) latest;
  IF NEW.id <= coalesce(latest_id, 0)
     OR NEW.id > coalesce(pg_sequence_last_value('public.ledger_entries_id_seq'::regclass), 0) THEN
    RAISE EXCEPTION 'a % event takes an id after its accounts'' latest events, from the sequence',
      NEW.type
      USING ERRCODE = 'integrity_constraint_violation', CONSTRAINT = TG_NAME;
  END IF;
  IF (NEW.from_account_id IS NOT NULL AND NEW.from_balance_after_coin
        IS DISTINCT FROM ledger_account_last_after(NEW.from_account_id) - NEW.amount_coin)
     OR (NEW.to_account_id IS NOT NULL AND NEW.to_balance_after_coin
        IS DISTINCT FROM ledger_account_last_after(NEW.to_account_id) + NEW.amount_coin) THEN
    RAISE EXCEPTION 'a % event does not continue its accounts'' totals', NEW.type
      USING ERRCODE = 'integrity_constraint_violation', CONSTRAINT = TG_NAME;
  END IF;
  RETURN NEW;
END;
$$;--> statement-breakpoint
-- Hand-edited: what a correction owes one account in one market (144-1 "올바른 결과였다면 받았을
-- 지급 합계 − 실제로 받은 지급 합계를 YES·NO를 합쳐"): Σ qty × the corrected result's per-contract
-- payout − Σ the paid payouts over the account's settlement records of the market — negative when
-- the paid result over-paid it, 0 when even, 0 with no record (an account that sold out before the
-- payout). The per-contract payout is exactly the CASE of `position_settlements_payout_check`
-- (0064) with the corrected result in place of the paid one, so the two SQL copies are visibly one
-- rule; @buddha/shared `judgementCompensationOwed` is its twin, which the db tests hold equal on
-- every (result, outcome). Reads `position_settlements` by its primary key (market, user, …).
CREATE FUNCTION judgement_compensation_owed(p_market uuid, p_corrected market_result, p_user text)
RETURNS bigint
LANGUAGE sql STABLE SET search_path = pg_catalog, public, pg_temp AS $$
  SELECT coalesce(sum(ps.qty::bigint * CASE WHEN p_corrected = 'VOID' THEN 50 WHEN p_corrected::text = ps.outcome::text THEN 100 ELSE 0 END - ps.payout_coin), 0)::bigint
  FROM position_settlements ps
  WHERE ps.market_id = p_market AND ps.user_id = p_user;
$$;--> statement-breakpoint
-- Hand-edited: a compensation is a permanent fact like its entry, whoever writes; buddha_app keeps
-- SELECT/INSERT of the default privileges in docker/postgres/init/01-roles.sql and loses UPDATE
-- and DELETE. Emptying the table (the reset, wipe.ts) fires no row trigger.
REVOKE UPDATE, DELETE ON TABLE "judgement_compensations" FROM buddha_app;--> statement-breakpoint
CREATE FUNCTION judgement_compensations_keep_record() RETURNS trigger
LANGUAGE plpgsql SET search_path = pg_catalog, public, pg_temp AS $$
BEGIN
  RAISE EXCEPTION 'judgement compensation % is a permanent record and takes no %', OLD.id, TG_OP
    USING ERRCODE = 'integrity_constraint_violation', CONSTRAINT = TG_NAME;
END;
$$;--> statement-breakpoint
CREATE TRIGGER judgement_compensations_keep_record
  BEFORE UPDATE OR DELETE ON "judgement_compensations"
  FOR EACH ROW EXECUTE FUNCTION judgement_compensations_keep_record();--> statement-breakpoint
-- Hand-edited: a row is its approved request's, whoever writes (the patterns of 0065's
-- reconciliation_recoveries_check and 0064's position_settlements_check):
-- - written by the transaction that approves the request (`applied_txid`, as 0070's recall rows);
-- - the request is an approved `market_judgement_compensation` of this market, its requester and
--   decider the row's, its `decided_at` the row's `created_at` (the decision's one instant), its
--   frozen payload naming this incident, this account with this amount among its recipients, and
--   this members' reason (144-12);
-- - the incident is confirmed on this market, its corrected result the payload's, and its paid
--   version's registrant is not the approver (144-4 — approval_requests_compensation_registrant
--   below refuses the decision itself);
-- - the account is a person's (`is_human_account`, 0059: never the 운영 마켓메이커, which has no user
--   ledger account), the amount is what its settlement records owe it now
--   (`judgement_compensation_owed`), and the row is `closed` exactly when the account is closed —
--   its profile read FOR KEY SHARE, so a closure in flight is waited for, and an account without a
--   profile is no open one (144-7: '탈퇴로 지급 못 함');
-- - the market is not ledger-held (#93): no unrecovered `reconciliation_holds` row and no
--   `ledger_failure` pause lasting or ended at the close without its recovery (the predicate of
--   0070's recall check and @buddha/db `ledgerHeldMarketSql`) — its settlement records are what
--   the amount is computed from.
-- No admin-role check on either admin, as market_judgements has none: the approver's role is the
-- approval engine's under the shared admin-roles lock. Fires before `_own_entry` (by name). Runs
-- as the invoker: buddha_app may SELECT every table read; the search path is fixed with pg_temp
-- last (0034, 0060).
CREATE FUNCTION judgement_compensations_check() RETURNS trigger
LANGUAGE plpgsql SET search_path = pg_catalog, public, pg_temp AS $$
DECLARE
  approval approval_requests%ROWTYPE;
  incident market_judgement_incidents%ROWTYPE;
  closed boolean;
BEGIN
  IF NEW.applied_txid IS DISTINCT FROM pg_current_xact_id()::text THEN
    RAISE EXCEPTION 'judgement compensation % is written by the transaction that approves it', NEW.id
      USING ERRCODE = 'integrity_constraint_violation', CONSTRAINT = TG_NAME;
  END IF;
  SELECT * INTO approval FROM approval_requests WHERE id = NEW.approval_id;
  IF approval.id IS NULL OR approval.kind <> 'market_judgement_compensation'
    OR approval.status::text <> 'approved'
    OR approval.target_type IS DISTINCT FROM 'market'
    OR approval.target_id IS DISTINCT FROM NEW.market_id::text
    OR approval.requested_by IS DISTINCT FROM NEW.requested_by
    OR approval.decided_by IS DISTINCT FROM NEW.approved_by
    OR approval.decided_at IS DISTINCT FROM NEW.created_at
    OR approval.payload ->> 'incidentId' IS DISTINCT FROM NEW.incident_id::text
    OR approval.payload ->> 'userReason' IS DISTINCT FROM NEW.user_reason
    OR jsonb_typeof(approval.payload -> 'recipients') IS DISTINCT FROM 'array'
    OR NOT (approval.payload -> 'recipients') @> jsonb_build_array(jsonb_build_object(
      'userId', NEW.user_id, 'amountCoin', NEW.amount_coin::text)) THEN
    RAISE EXCEPTION 'judgement compensation % needs its approved market_judgement_compensation request listing it', NEW.id
      USING ERRCODE = 'integrity_constraint_violation', CONSTRAINT = TG_NAME;
  END IF;
  SELECT * INTO incident FROM market_judgement_incidents WHERE id = NEW.incident_id;
  IF incident.id IS NULL OR incident.market_id IS DISTINCT FROM NEW.market_id
    OR approval.payload ->> 'correctedResult' IS DISTINCT FROM incident.corrected_result::text THEN
    RAISE EXCEPTION 'judgement compensation % names its market''s confirmed incident', NEW.id
      USING ERRCODE = 'integrity_constraint_violation', CONSTRAINT = TG_NAME;
  END IF;
  IF NEW.approved_by = incident.paid_registered_by THEN
    RAISE EXCEPTION 'the paid judgement version''s registrant does not approve judgement compensation %', NEW.id
      USING ERRCODE = 'integrity_constraint_violation', CONSTRAINT = TG_NAME;
  END IF;
  IF NOT is_human_account(NEW.user_id) THEN
    RAISE EXCEPTION 'account % is not a person''s: it takes no judgement compensation', NEW.user_id
      USING ERRCODE = 'integrity_constraint_violation', CONSTRAINT = TG_NAME;
  END IF;
  IF NEW.amount_coin IS DISTINCT FROM
      judgement_compensation_owed(NEW.market_id, incident.corrected_result, NEW.user_id) THEN
    RAISE EXCEPTION 'judgement compensation % is not what the settlement records owe its account', NEW.id
      USING ERRCODE = 'integrity_constraint_violation', CONSTRAINT = TG_NAME;
  END IF;
  SELECT p.closed_at IS NOT NULL INTO closed FROM profiles p
    WHERE p.user_id = NEW.user_id FOR KEY SHARE;
  IF (NEW.outcome = 'closed') IS DISTINCT FROM coalesce(closed, true) THEN
    RAISE EXCEPTION 'judgement compensation % is closed exactly when its account is', NEW.id
      USING ERRCODE = 'integrity_constraint_violation', CONSTRAINT = TG_NAME;
  END IF;
  IF EXISTS (SELECT 1 FROM reconciliation_holds h
      WHERE h.market_id = NEW.market_id AND h.recovered_at IS NULL)
    OR EXISTS (SELECT 1 FROM market_pauses p
      WHERE p.market_id = NEW.market_id AND p.reason = 'ledger_failure'
        AND (p.ended_at IS NULL OR p.end_kind = 'closed_at_close')
        AND NOT EXISTS (SELECT 1 FROM reconciliation_recoveries r WHERE r.legacy_pause_id = p.id)) THEN
    RAISE EXCEPTION 'judgement compensation % waits while its market is ledger-held', NEW.id
      USING ERRCODE = 'integrity_constraint_violation', CONSTRAINT = TG_NAME;
  END IF;
  RETURN NEW;
END;
$$;--> statement-breakpoint
CREATE TRIGGER judgement_compensations_check
  BEFORE INSERT ON "judgement_compensations"
  FOR EACH ROW EXECUTE FUNCTION judgement_compensations_check();--> statement-breakpoint
-- Hand-edited: a `paid` row is its own JUDGEMENT_COMPENSATION entry's, whoever writes (0077's
-- regrants_own_entry) — the entry this row names is of the type, refers to this row, is keyed by
-- the request and the account (`ledgerKeys.judgementCompensation`), mints this amount into this
-- account's user ledger account, names this market and carries this row's instant. So the record
-- and the ledger never tell two stories, and a row cannot claim another account's, another
-- market's or another type's entry (each entry backs one row: the UNIQUE `ledger_entry_id`). A
-- `closed` row names none (the outcome CHECK). Fires after `_check` (by name).
CREATE FUNCTION judgement_compensations_own_entry() RETURNS trigger
LANGUAGE plpgsql SET search_path = pg_catalog, public, pg_temp AS $$
BEGIN
  IF NEW.outcome = 'paid' AND NOT EXISTS (
    SELECT 1 FROM ledger_entries e
    JOIN ledger_accounts a ON a.id = e.to_account_id
    WHERE e.id = NEW.ledger_entry_id
      AND e.type::text = 'JUDGEMENT_COMPENSATION'
      AND e.ref_type = 'judgement_compensation'
      AND e.ref_id = NEW.id::text
      AND e.idempotency_key = NEW.approval_id::text || ':' || NEW.user_id
      AND e.amount_coin = NEW.amount_coin
      AND e.from_account_id IS NULL
      AND a.kind = 'user'
      AND a.owner_id = NEW.user_id
      AND e.market_id = NEW.market_id
      AND e.created_at = NEW.created_at
  ) THEN
    RAISE EXCEPTION 'judgement compensation % is paid only with its own JUDGEMENT_COMPENSATION ledger entry', NEW.id
      USING ERRCODE = 'integrity_constraint_violation', CONSTRAINT = TG_NAME;
  END IF;
  RETURN NEW;
END;
$$;--> statement-breakpoint
CREATE TRIGGER judgement_compensations_own_entry
  BEFORE INSERT ON "judgement_compensations"
  FOR EACH ROW EXECUTE FUNCTION judgement_compensations_own_entry();--> statement-breakpoint
-- Hand-edited: and a JUDGEMENT_COMPENSATION entry is recorded only with its row, by the end of its
-- transaction — the type and the reference come together, and the row that names the entry is the
-- one it refers to (0077's ledger_entries_regrant_record). Deferred, as the row is inserted after
-- its entry (it names the entry's id). With the triggers above, no Coin is ever compensated
-- without an approved request's record of it (#144 AC 5), and no record stands without its Coin.
CREATE FUNCTION ledger_entries_judgement_compensation_record() RETURNS trigger
LANGUAGE plpgsql SET search_path = pg_catalog, public, pg_temp AS $$
BEGIN
  IF NOT (NEW.type::text = 'JUDGEMENT_COMPENSATION' AND NEW.ref_type = 'judgement_compensation'
    AND EXISTS (
      SELECT 1 FROM judgement_compensations c
      WHERE c.ledger_entry_id = NEW.id AND c.id::text = NEW.ref_id
    )) THEN
    RAISE EXCEPTION 'ledger entry % is a judgement compensation only as its judgement_compensations row''s own', NEW.id
      USING ERRCODE = 'integrity_constraint_violation', CONSTRAINT = TG_NAME;
  END IF;
  RETURN NULL;
END;
$$;--> statement-breakpoint
CREATE CONSTRAINT TRIGGER ledger_entries_judgement_compensation_record
  AFTER INSERT ON "ledger_entries"
  DEFERRABLE INITIALLY DEFERRED
  FOR EACH ROW
  WHEN (NEW.type::text = 'JUDGEMENT_COMPENSATION' OR NEW.ref_type = 'judgement_compensation')
  EXECUTE FUNCTION ledger_entries_judgement_compensation_record();--> statement-breakpoint
-- Hand-edited: 144-4 at the approval itself — the paid version's registrant (the
-- market_judgements row at the market's current version) never approves a compensation of the
-- market (0080's approval_requests_incident_registrant for 오류 확인·기각). Approval only: a 반려
-- is a 정리 목적 반려 (ADR-0120 decision 5 "정리 목적의 반려·철회는 새 배제에 포함하지 않는다") and
-- 144-4 bars only 보상 승인. The requester is approval_requests_decider_not_requester_check's.
-- Compared as text and varchar, so no enum value of this batch is named.
CREATE FUNCTION approval_requests_compensation_registrant() RETURNS trigger
LANGUAGE plpgsql SET search_path = pg_catalog, public, pg_temp AS $$
BEGIN
  IF NEW.decided_by IS NOT NULL AND NEW.target_type = 'market' THEN
    IF EXISTS (
      SELECT 1 FROM markets m
      JOIN market_judgements j ON j.market_id = m.id AND j.version = m.judgement_version
      WHERE m.id = NEW.target_id::uuid AND j.registered_by = NEW.decided_by
    ) THEN
      RAISE EXCEPTION 'the paid judgement version''s registrant does not approve judgement compensation request %', NEW.id
        USING ERRCODE = 'integrity_constraint_violation', CONSTRAINT = TG_NAME;
    END IF;
  END IF;
  RETURN NEW;
END;
$$;--> statement-breakpoint
CREATE TRIGGER approval_requests_compensation_registrant
  BEFORE UPDATE ON "approval_requests"
  FOR EACH ROW
  WHEN (NEW.kind = 'market_judgement_compensation' AND OLD.status::text = 'pending'
    AND NEW.status::text = 'approved')
  EXECUTE FUNCTION approval_requests_compensation_registrant();--> statement-breakpoint
-- Hand-edited: and an approved compensation request commits only with one row per listed account,
-- their amounts summing to its frozen total (paid and closed alike), every one written by the
-- deciding transaction — "승인하면 목록의 계정마다 한 번씩 지급한다" (144-2) held by the database:
-- an approval with a missing, extra or later row is refused at COMMIT, and the whole approval
-- with it (0080's approval_requests_incident_record pattern). Each row's own trigger has put it on
-- the list with its amount, and UNIQUE (incident_id, user_id) keeps an account once, so the count
-- and the sum close the list.
CREATE FUNCTION approval_requests_compensation_record() RETURNS trigger
LANGUAGE plpgsql SET search_path = pg_catalog, public, pg_temp AS $$
DECLARE
  rows_written bigint;
  total numeric;
  later bigint;
BEGIN
  SELECT count(*), coalesce(sum(c.amount_coin), 0),
    count(*) FILTER (WHERE c.applied_txid IS DISTINCT FROM pg_current_xact_id()::text)
    INTO rows_written, total, later
    FROM judgement_compensations c WHERE c.approval_id = NEW.id;
  IF jsonb_typeof(NEW.payload -> 'recipients') IS DISTINCT FROM 'array'
    OR rows_written IS DISTINCT FROM (CASE WHEN jsonb_typeof(NEW.payload -> 'recipients') = 'array'
      THEN jsonb_array_length(NEW.payload -> 'recipients')::bigint END)
    OR total::text IS DISTINCT FROM NEW.payload ->> 'totalCoin'
    OR later <> 0 THEN
    RAISE EXCEPTION 'judgement compensation request % is approved only with a record of each listed account, written by the same transaction', NEW.id
      USING ERRCODE = 'integrity_constraint_violation', CONSTRAINT = TG_NAME;
  END IF;
  RETURN NULL;
END;
$$;--> statement-breakpoint
CREATE CONSTRAINT TRIGGER approval_requests_compensation_record
  AFTER UPDATE ON "approval_requests"
  DEFERRABLE INITIALLY DEFERRED
  FOR EACH ROW
  WHEN (NEW.kind = 'market_judgement_compensation' AND OLD.status::text = 'pending'
    AND NEW.status::text = 'approved')
  EXECUTE FUNCTION approval_requests_compensation_record();
